/** The devices a given design is sold for in a given case type. */
export function devicesFor(designSlug: string, caseTypeSlug: string): string[] {
  const setId = DESIGN_DEVICES[designSlug]?.[caseTypeSlug]
  if (setId) return DEVICE_SETS[setId]
  return CASE_TYPE_DEVICES[caseTypeSlug] ?? []
}
